from pathlib import Path
import html
import json

ROOT=Path('/workspace/sites/coral-classroom-redesign-artbook/dist')
manifest=json.loads(Path('/workspace/work/redesign-artbook/image-manifest.json').read_text())
images={entry['id']:entry for entry in manifest}

def figure(key,title,description,alt,eager=False):
    entry=images[key]
    width,height=entry['dimensions']
    src='assets/'+Path(entry['asset']).name
    return f'''<figure id="art-{key}"><div class="caption"><div><h3>{html.escape(title)}</h3><p>{html.escape(description)}</p></div><a class="full" href="{src}" target="_blank" rel="noopener">Open full size</a></div><a class="art" href="{src}" target="_blank" rel="noopener" aria-label="Open {html.escape(title)} full size"><img src="{src}" width="{width}" height="{height}" alt="{html.escape(alt)}" loading="{'eager' if eager else 'lazy'}" decoding="async" {'fetchpriority="high"' if eager else ''}></a></figure>'''

sections=[]
sections.append('''<section class="chapter" id="shelly-options"><p class="eyebrow">Character design survey</p><h2>Ten progressively baby-like Shellys.</h2><p class="intro">Compare ten 3D proportion studies, each shown in the same normal and top-down views. The range moves from subtle softening toward a large-headed hatchling. Choose a favorite before changing the game’s character.</p><p><a class="full" href="shelly-options.html">Compare all ten options</a></p></section>''')
sections.append('''<section class="chapter" id="play"><p class="eyebrow">Updated in-engine preview</p><h2>Shelly’s gentler face, seen from above.</h2><p class="intro">Shelly now has rounder, more forward-facing eyes and a softer forehead for the elevated board camera. Roll, move along the route and change the camera to inspect her in the crafted Coral Cove. This uses a separate demonstration profile; the illustrated gallery below remains concept artwork.</p><p><a class="full" href="play/?art=crafted&amp;shelly=storybook&amp;v=crafted-3">Open the updated Coral Cove preview</a> <a class="full" href="shelly.html?v=organic-3&amp;angle=top">See Shelly from above</a></p><p class="small">The visual prototype continues toward the approved direction. Phone frame rate has not been measured.</p></section>''')
sections.append(figure('coral-cove','Coral Cove · the visual foundation','Living characters in a crafted ocean: smooth sculpted stone, softly lit satin glass and a painted reef beyond the playable path.','Organic mint Shelly with a lavender shell beside pale dimensional travel tiles and shell-shaped stone and colored-glass reef architecture.',True))
sections.append('''<section id="characters" class="chapter"><p class="eyebrow">Characters & conversations</p><h2>Living creatures. Individual personalities.</h2><p class="intro">Organic skin, scales, shells and fins share the world’s soft color and light. Clothing supports each occupation; it does not turn the animals into people.</p>''')
sections.append(figure('characters','A neighborhood of marine residents','Shelly, tiny postal courier Jisu, the adult octopus shopkeeper, Echo the beluga, Pip the royal gramma and Hana the jellyfish. The revised turtle pose makes the flipper attachments clearer.','Six marine characters of distinct sizes in a stone and glass court: turtle, hermit crab, octopus, white beluga, purple and yellow fish, and peach jellyfish.'))
sections.append(figure('encounter','At the café · a language encounter','A close conversation brings the resident into view. A calm, mostly 2D lesson panel keeps the Korean phrase, translation and listening controls readable.','Shelly faces a peach seahorse barista behind a stone counter. Below, a lesson panel reads 커피 한 잔 주세요 and One coffee, please.'))
sections.append('''<aside><h3>Anatomy is part of every review</h3><p>Shelly and Mira have four flippers. Octopus arms must be independent and unbranched; fish retain fins; Echo has no dorsal fin. Occluded limbs are checked in turnarounds and models rather than added to make every limb visible. Character construction, animation and final screen framing each need their own check.</p><p class="small">These are illustrations, not validated 3D assets. The group shot cannot establish the full count of hidden crab legs or octopus arms.</p></aside></section>''')
sections.append('''<section id="regions" class="chapter"><p class="eyebrow">Eight destinations</p><h2>A world you can recognize by its silhouette.</h2><p class="intro">Coral Cove establishes the material language. The other destinations change their landmarks, route compositions, light and material balance. The pictures show visual direction; final route graphs still need gameplay validation.</p>''')
sections.append(figure('harbor','Harbor Town · quays, markets and a working waterfront','A horseshoe harbor, moored ship, clock-and-bell tower and market island give the town a distinct layout. Painted timber and awnings add working-town color beside stone and restrained glass.','Harbor Town map with a looping dimensional tile path around a turquoise harbor, ship, bridge, clock tower, stalls and marine shopkeepers.'))
sections.append(figure('lagoon-caves','Story Lagoon & Echo Caves','The lagoon opens around a lily-shaped story pavilion and garden water. The caves enclose an echo basin with large blue stone arches and focused pools of light.','Two map concepts: a jade lagoon with turtle Mira, lily pavilion and gardens; a cobalt cave with beluga Echo, stone arches and a circular tile route.'))
sections.append(figure('patterns-beach','Pattern Reef & Bottle Beach','Rhythmic mosaic terraces and a glass ring define the reef. Warm sandstone, ivory sand and a bottle-shaped post office define the shoreline.','Two map concepts: patterned violet and yellow coral terraces with royal gramma Pip; a sandy shore with a frosted bottle post office and hermit crab Jisu.'))
sections.append(figure('lighthouse-captain','The Lighthouse & Captain’s Deck','A spiral stone beacon rises above a deep blue ridge. The captain’s world is a ship with a curved prow, raised stern and inset deck tiles, using more painted timber.','Two map concepts: a stone lighthouse circuit with jellyfish Hana over a blue abyss, and a ship deck with walrus Captain Bay at a compass table.'))
sections.append('''</section><section id="menus" class="chapter"><p class="eyebrow">Menus & learning screens</p><h2>Painted depth. Simple screens.</h2><p class="intro">These can be illustrated 2D surfaces with real text and controls layered above them. Depth comes from composition, shading and carefully chosen motion.</p>''')
sections.append(figure('home','Home & profile selection','The revised Shelly has two visible foreflippers and one visible hindflipper; her other hindflipper is hidden behind her body. The home screen uses illustrated scenery instead of a continuously rendered 3D scene.','Home-screen concept with organic Shelly, three marine profile choices and Continue exploring, Choose a region, Word Bank, My Progress and Grown-ups controls.'))
sections.append(figure('world-map','Choose a region · an illustrated sea chart','Eight miniature destinations make the next stop easy to recognize. A mostly 2D chart can suggest relief and depth without loading all eight playable regions.','A relief-style painted sea map showing the eight labeled Coral Classroom destinations joined by soft ocean currents.'))
sections.append(figure('study-library','Vocabulary practice & Word Bank','Quiet card surfaces reserve attention for Korean text, audio and review choices. In the game these labels will be live text, not text baked into a background image.','Two study-menu concepts: a 바다 sea vocabulary card with Listen and review choices, and a Word Bank with 바다 sea, 물 water and 집 house.'))
sections.append('''</section><section id="approach" class="chapter approach"><p class="eyebrow">The production approach</p><h2>Use depth where the player needs it.</h2><div class="columns"><div><h3>Illustrated 2D</h3><p>Menus, study cards, the sea chart and distant scenery. Paint surface richness and contact shading instead of building every detail.</p></div><div><h3>A layered world</h3><p>Use simple dimensional paths, terrain and nearby landmarks with painted surfaces. Layer distant scenery in world space so it holds together as the camera moves.</p></div><div><h3>Selective 3D</h3><p>Keep useful depth for tile hopping, near characters and close conversations. Load detailed residents and regional assets when they are needed.</p></div></div><p class="small">The iPhone XS remains the performance target. These static concepts do not demonstrate frame rate; the implemented assets and camera movement will need device testing.</p></section>''')

